arguments.command:
python -c "
import parse
r = parse.parse('''
    letters: {:w}
    non-letters: {:W}
    whitespace: \"{s}\"
    non-whitespace: \t{S}\n
    digits: {d} {d}
    non-digits: {D}
    numbers with thousands: {n}
    fixed-point: {f}
    floating-point: {e}
    general numbers: {g} {g}
    binary: {b}
    octal: {o}
    hex: {x}
''', '''
    letters: abcdef_GHIJLK
    non-letters: !@#%$ *^%
    whitespace: \"   \\t\\n\"
    non-whitespace: \tabc\n
    digits: 12345 0b1011011
    non-digits: abcdef
    numbers with thousands: 1,000
    fixed-point: 100.2345
    floating-point: 1.1e-10
    general numbers: 100.2345 1000000
    binary: 0b1011011
    octal: 0o755
    hex: 0xFF
''')
print(r)
" 2>&1
